create extension if not exists pgcrypto;
create table organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,website text,organization_type text,official_domains text[] default '{}',public_contact_email text,public_contact_phone text,address text,city text,state text,postal_code text,verification_status text not null default 'unverified',verification_method text,verified_at timestamptz,next_verification_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table opportunities(id text primary key,organization_id uuid references organizations, title text not null,slug text unique not null,summary text not null,description text,category text not null,subcategory text,audience text,status text not null check(status in('open','ongoing','upcoming','closed','verify','removed')),format text,address text,city text,state text,postal_code text,latitude numeric,longitude numeric,transportation_notes text,application_url text,public_contact_email text,opens_at timestamptz,deadline_at timestamptz,starts_at timestamptz,ends_at timestamptz,recurrence_text text,expected_hours_min numeric,expected_hours_max numeric,effort_level text,fee_min numeric,fee_max numeric,cost_unknown boolean not null default true,financial_aid_available boolean,compensation_type text,compensation_min numeric,compensation_max numeric,currency text default 'USD',compensation_notes text,application_effort text[],requirements_text text,accessibility_text text,source_url text not null,source_type text,source_publisher text,source_updated_at timestamptz,last_verified_at timestamptz not null,confidence text not null,published_at timestamptz,closed_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create index opportunities_status_idx on opportunities(status);create index opportunities_deadline_idx on opportunities(deadline_at);create index opportunities_category_idx on opportunities(category);create index opportunities_location_idx on opportunities(city,state);create index opportunities_verified_idx on opportunities(last_verified_at,confidence);
create table eligibility_rules(id uuid primary key default gen_random_uuid(),opportunity_id text references opportunities on delete cascade,field text not null,operator text not null,value jsonb not null,source_text text,certainty text not null,is_hard_requirement boolean not null default false);
create table taxonomy_nodes(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,type text not null,parent_id uuid references taxonomy_nodes,synonyms text[] default '{}');
create table opportunity_taxonomy(opportunity_id text references opportunities on delete cascade,taxonomy_node_id uuid references taxonomy_nodes on delete cascade,weight numeric not null default 1,evidence_source text,primary key(opportunity_id,taxonomy_node_id));
create table source_records(id uuid primary key default gen_random_uuid(),opportunity_id text references opportunities on delete cascade,url text not null,source_type text,publisher text,captured_at timestamptz default now(),source_updated_at timestamptz,content_hash text,excerpt text,extraction_method text,permission_notes text);
create table profiles(user_id uuid primary key references auth.users on delete cascade,display_name text,role text not null default 'student',school text,grade smallint,onboarding_completed_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table saved_opportunities(user_id uuid references auth.users on delete cascade,opportunity_id text references opportunities on delete cascade,status text default 'saved',private_notes text,created_at timestamptz default now(),updated_at timestamptz default now(),primary key(user_id,opportunity_id));
create table reminders(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users on delete cascade,opportunity_id text references opportunities on delete cascade,reminder_at timestamptz not null,channel text not null,sent_at timestamptz,cancelled_at timestamptz);
create table submissions(id uuid primary key default gen_random_uuid(),submitter_user_id uuid references auth.users on delete set null,submitter_role text,organization_name text,proposed_data jsonb not null,evidence_url text,submitter_email text,moderation_status text not null default 'pending',reviewer_notes text,created_at timestamptz default now(),reviewed_at timestamptz);
create table change_requests(id uuid primary key default gen_random_uuid(),opportunity_id text references opportunities,proposed_changes jsonb not null,evidence text,requester_user_id uuid references auth.users on delete set null,moderation_state text default 'pending',created_at timestamptz default now(),reviewed_at timestamptz);
create table organization_claims(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations,claimant_user_id uuid references auth.users,institutional_email text,verification_method text,status text default 'pending',verified_at timestamptz,expires_at timestamptz);
create table source_channels(id uuid primary key default gen_random_uuid(),name text,url text,coverage text,review_cadence text,preferred_ingestion_method text,priority text,terms_robots_notes text,owner text,last_checked timestamptz,next_check timestamptz,status text);
create table import_batches(id uuid primary key default gen_random_uuid(),content_hash text unique not null,filename text not null,started_at timestamptz default now(),completed_at timestamptz,accepted_count int default 0,rejected_count int default 0,report jsonb);
create table moderation_events(id uuid primary key default gen_random_uuid(),actor uuid references auth.users,entity_type text,entity_id text,action text,before_snapshot jsonb,after_snapshot jsonb,reason text,created_at timestamptz default now());
create table analytics_events(id bigint generated always as identity primary key,pseudonymous_id text,event_name text not null,opportunity_id text,coarse_page text,category text,campaign_tag text,created_at timestamptz default now());
alter table profiles enable row level security;alter table saved_opportunities enable row level security;alter table reminders enable row level security;alter table submissions enable row level security;alter table change_requests enable row level security;alter table organization_claims enable row level security;alter table opportunities enable row level security;
create policy "public reads published opportunities" on opportunities for select using(published_at is not null and status in('open','ongoing','upcoming'));
create policy "users read own profile" on profiles for select using(auth.uid()=user_id);create policy "users update own profile" on profiles for update using(auth.uid()=user_id);
create policy "users manage own saves" on saved_opportunities for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "users manage own reminders" on reminders for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "users read own submissions" on submissions for select using(auth.uid()=submitter_user_id);create policy "anyone submits pending" on submissions for insert with check(moderation_status='pending');
